sp_widget.client_script:
function($scope, $location) {
  $scope.goTo = function(id) {
    //$location.url("?id=" + id);
		window.open("?id=" + id, '_blank');
  };

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

}

sp_widget.css:
.servicos-widget {
  font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 80%;
  margin: 25px auto 3rem auto; /* centraliza horizontalmente e adiciona margem superior */
  position: static;
  text-align: center; /* garante que o texto também fique centralizado */
}

.grafico-rcl {
  max-width: 68.5rem; /* Aqui é onde você define o tamanho máximo */
  margin: 32px auto;
  padding: 24px;
  box-sizing: border-box;
  border: 1px solid #ccc;
  border-radius: 10px;
  background-color: #f9f9f9;
  box-shadow: 0 0 8px rgba(0, 0, 0, 0.05);
  min-height: 30rem;
	//max-height: 50rem;
}


.grafico-rcl h3 {
    font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
  text-align: center;
  font-size: 2.5rem;
  margin-bottom: 24px;
}

.grafico-rcl img {
  width: 100%;
  height: auto;
  max-height: 300px;
  margin-bottom: 24px;
  border-radius: 6px;
}

.grafico-rcl p {
    font-family: 'Roboto Flex', sans-serif !important;
  font-weight: 400;
  font-size: 2rem;
  line-height: 1.6;
  text-align: justify;
  margin-bottom: 24px;
}

/*
.grafico-rcl button {
    font-family: 'Roboto Flex', sans-serif !important;
    font-weight: 400;
    display: block;
    margin-left: auto; 
    padding: 12px 24px;
    font-size: 2rem;
    cursor: pointer;
     border-radius: 3rem;
}*/
.grafico-rcl {
  font-family: 'Roboto Flex', sans-serif !important;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
   	height: 71.8rem;;
  max-width: 68.5rem; /* Aqui é onde você define o tamanho máximo */
  margin: 32px auto;
  padding: 24px;
  box-sizing: border-box;
  border: 1px solid #ccc;
  border-radius: 10px;
  background-color: #f9f9f9;
  box-shadow: 0 0 8px rgba(0, 0, 0, 0.05);
  min-height: 30rem;
}

.grafico-rcl button {
  font-weight: 400;
  font-family: 'Roboto Flex', sans-serif !important;
    align-self: flex-end;
    padding: 12px 24px;
    font-size: 2rem;
    border-radius: 3rem;
   font-size: 2rem;
   cursor: pointer;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}



@media (max-width: 768px) {
  .grafico-rcl {
    padding: 16px;
  }

  .grafico-rcl h3 {
    font-size: 1.25rem;
  }

  .grafico-rcl p {
    font-size: 0.95rem;
  }

  .grafico-rcl button {
    width: 100%;
  }
}

@media (max-width: 1320px) {
  .grafico-rcl {
   height: 74.9rem;;
  }
}

@media (max-width: 1060px) {
  .grafico-rcl {
   height: 81.3rem;
  }
}
